#!/usr/bin/env node
/**
 * test-prop-113.js — PROP-113 smoke test (Fix A invariant + Fix B parser).
 * Self-contained: builds synthetic archives in a tmp dir, exercises the
 * hardened set-builder, and asserts the Fix A overcount invariant. Run from
 * repo root: `node monitor/scripts/test-prop-113.js`. Exit 0 = all pass.
 *
 * Covers:
 *   T1 (Fix B parity)      — clean archives: builder output == naive jq/awk output.
 *   T2 (Fix B garbage)     — newline-fragment + absolute-path + traversal records
 *                            are dropped, never emitted.
 *   T3 (Fix B colon paths) — ISO-timestamp filenames with ':' are kept (regression
 *                            guard: the PROP-113-as-written regex dropped these).
 *   T4 (Fix A invariant)   — unique-path count can never exceed record count on
 *                            well-formed input; a corrupt build that does is the
 *                            exact signal Fix A's GIT_DELETED_COUNT>ARCHIVE_LINES trips.
 */
const fs = require('fs'), os = require('os'), path = require('path'), cp = require('child_process');
const BUILDER = path.join(__dirname, 'build-git-deleted-set.js');
let pass = 0, fail = 0;
const ok = (n, c) => { if (c) { pass++; console.log('  PASS', n); } else { fail++; console.log('  FAIL', n); } };

function mkArchives(records) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'prop113-'));
  const idir = path.join(dir, 'monitor', 'integrity');
  fs.mkdirSync(idir, { recursive: true });
  fs.writeFileSync(path.join(idir, 'narrative-cite-audit-archive.jsonl'),
    records.map(r => JSON.stringify(r)).join('\n') + '\n');
  return { dir, idir };
}
function build(idir) {
  const out = path.join(os.tmpdir(), 'prop113-out-' + Math.random().toString(36).slice(2));
  const r = cp.spawnSync('node', [BUILDER, '--integrity-dir', idir, '--out', out], { encoding: 'utf8' });
  const lines = fs.existsSync(out) ? fs.readFileSync(out, 'utf8').split('\n').filter(Boolean) : [];
  let summary = {}; try { summary = JSON.parse((r.stderr || '').trim().split('\n').pop()); } catch (e) {}
  return { lines, summary };
}

// T1 parity
let a = mkArchives([
  { file: 'monitor/integrity/narrative-cite-audit-2026-06-01T0100Z.json' },
  { file: 'narrative-cite-audit-2026-06-01T0200Z.json' },              // bare basename -> prefixed
  { file: 'monitor/integrity/narrative-cite-audit-2026-06-01T0100Z.json' } // dup -> collapses
]);
let b = build(a.idir);
ok('T1 parity (2 unique from 3 records)', b.lines.length === 2);

// T2 garbage
a = mkArchives([
  { file: 'monitor/integrity/good-2026-06-01T0100Z.json' },
  { file: 'monitor/integrity/bad\nprose fragment\n../../etc/passwd' },
  { file: '/abs/evil.json' },
  { file: 'monitor/integrity/../escape.json' }
]);
b = build(a.idir);
ok('T2 garbage dropped (only 1 good path emitted)', b.lines.length === 1 && b.lines[0].endsWith('good-2026-06-01T0100Z.json'));
ok('T2 rejected counted (>=3)', (b.summary.rejected || 0) >= 3);

// T3 colon paths kept
a = mkArchives([{ file: 'monitor/integrity/push-failure-2026-05-06T13:21:02Z.json' }]);
b = build(a.idir);
ok('T3 ISO-colon filename kept', b.lines.length === 1);

// T4 Fix A invariant: clean build never exceeds record count
a = mkArchives(Array.from({ length: 100 }, (_, i) => ({ file: `monitor/integrity/x-${i}.json` })));
b = build(a.idir);
ok('T4 unique<=records invariant holds (Fix A floor)', b.summary.paths_emitted <= b.summary.records_seen);

console.log(`\nPROP-113 smoke test: ${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
